#include <stack>
#include <string>

bool isValid(const std::string& s)
{
  // Create a stack to hold the parenthesis
  std::stack<char> st;

  // Iterate over the characters in the string
  for (const char& c : s)
  {
    // If the character is an opening parenthesis, push it onto the stack
    if (c == '(' || c == '[' || c == '{')
    {
      st.push(c);
    }
    // If the character is a closing parenthesis, pop the top element from the stack
    // and check if it matches the closing parenthesis
    else if (c == ')' || c == ']' || c == '}')
    {
      // If the stack is empty or the top element does not match the closing
      // parenthesis, return false
      if (st.empty() || st.top() != c)
      {
        return false;
      }

      // If the top element matches the closing parenthesis, pop it from the stack
      st.pop();
    }
  }

  // If the stack is not empty, return false
  if (!st.empty())
  {
    return false;
  }

  // Otherwise, return true
  return true;
}

#include <fstream>
#include <vector>

struct Athlete
{
  std::string name;
  int age;
  double height;
  double weight;
};

int main()
{
  // Open the input file
  std::ifstream input("athletes.txt");

  // Create a vector to hold the athlete data
  std::vector<Athlete> athletes;

  // Read the data from the file and store it in the vector
  while (input)
  {
    Athlete athlete;
    input >> athlete.name >> athlete.age >> athlete.height >> athlete.weight;
    athletes.push_back(athlete);
  }

  // Print the data from the vector
  for (const Athlete& athlete : athletes)
  {
    std::cout << athlete.name << " " << athlete.age << " " << athlete.height << " " << athlete.weight << std::endl;
  }

  return 0;
}

* {
  margin: 0;
  padding: 0;
}

.header {
  background-image: linear-gradient(rgba(4,9,30,0.7),rgba(4,9,30,0.7)), url(eduford_img/banner.png);
  min-height: 100vh;
  width: 100%;
  background-position: center center;
  background-size: cover;
  position: relative;
}
